import { chacha20poly1305 as chacha20poly1305noble } from '@noble/ciphers/chacha'
import { assertUint8 } from './utils/assertUint8.mjs'
import { createCipherApi, directMethods } from './utils/cipher.mjs'

export async function chacha20poly1305(key, usage) {
  assertUint8(key, 32, 'key')
  return createCipherApi(usage, {
    async encrypt(data, nonce, additionalData) {
      assertUint8(nonce, 12, 'nonce')
      const chacha = chacha20poly1305noble(key, nonce, additionalData)
      return chacha.encrypt(data)
    },
    async decrypt(data, nonce, additionalData) {
      assertUint8(nonce, 12, 'nonce')
      const chacha = chacha20poly1305noble(key, nonce, additionalData)
      return chacha.decrypt(data)
    },
  })
}

const { encrypt: encryptChacha20poly1305, decrypt: decryptChacha20poly1305 } =
  directMethods(chacha20poly1305)

export { encryptChacha20poly1305, decryptChacha20poly1305 }
